import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("claim comments", () => {
  test("claim comments", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.addComment(pg_uma, c_ada_0, "first")).toBe(true);
    expect(await ui.addComment(pg_uma, c_ada_0, " ")).toBe(false);
    expect(await ui.addComment(pg_uma, c_ada_1, "draft note")).toBe(true);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    await ui.setToday(pg_vic, "2026-03-11");
    expect(await ui.addComment(pg_vic, c_ada_0, "second")).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.addComment(pg_wes, c_ada_0, "nope")).toBe(false);
    await ui.refresh(pg_vic);
    expect(await ui.claimAction(pg_vic, c_ada_0, "settle")).toBe(true);
    expect(await ui.addComment(pg_vic, c_ada_0, "paid")).toBe(true);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-comments-line")).toHaveText(["uma on 2026-03-10: draft note"]);
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-comments-line")).toHaveText(["uma on 2026-03-10: first", "vic on 2026-03-11: second", "vic on 2026-03-11: paid"]);
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("SETTLED");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `ROLE_SET sheet=${sheet} by=uma user=wes role=viewer`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10 number=1`,
      `ROLLUP sheet=${sheet} by=uma person=Ada claimed=10.00 due-total=1.00 overdue-total=0.00`,
      `TOTALS sheet=${sheet} by=uma claimed-total=10.00 due-total=1.00 overdue-total=0.00`,
      `COMMENT_ADDED sheet=${sheet} by=uma person=Ada amount=10.00 date=2026-03-10 number=1 text=first`,
      `COMMENT_ADDED sheet=${sheet} by=uma person=Ada amount=20.00 date=2026-03-10 text=draft note`,
      `SNAPSHOT sheet=${sheet} by=vic name=Ada due-total=1.00`,
      `COMMENT_ADDED sheet=${sheet} by=vic person=Ada amount=10.00 date=2026-03-10 number=1 text=second`,
      `CLAIM_SETTLED sheet=${sheet} by=vic person=Ada amount=10.00 date=2026-03-10 number=1 due=1.00`,
      `COMMENT_ADDED sheet=${sheet} by=vic person=Ada amount=10.00 date=2026-03-10 number=1 text=paid`
    ]);
  });
