import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The claims on a sheet. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class ClaimController {

    /** A claim, with who opened it (null until opened), whether it is bound to the figure it had at its
     * person's last statement, its status log and the date it was last deferred until (null when never
     * deferred; it is deferred while OPEN and the sheet's today is before that date), its proofs count, whether it was added while its period was soft-closed (one line per status it has had, oldest first); its amount, what was due on it when settled (null otherwise) and
     * the figure it is bound to (null when unbound or bound to no figure), and the date it was last reminded
     * (null when never), are sent as text with two
     * decimals so they are never rounded on the way. */
    public record ClaimView(long id, long personId, String amount, LocalDate date, LocalDate dueBy, String note,
            ClaimStatus status, String number, String settledDue,
            String openedBy, boolean stated, String statedDue, String corrects, List<String> log,
            LocalDate deferredUntil, int proofs, String splitFrom, boolean lateEntry, LocalDate remindedOn,
            String ref, List<String> tags, String voidReason) {
        /** The claims as views, each with its status log, in the order given. */
        public static List<ClaimView> allOf(List<Claim> claims, ClaimService service) {
            Map<Long, List<ClaimLog>> logs = service.logsOf(claims);
            return claims.stream().map(c -> of(c, logs.getOrDefault(c.getId(), List.of()))).toList();
        }

        /** The claim as a view, with its status log. */
        public static ClaimView of(Claim claim, ClaimService service) {
            return allOf(List.of(claim), service).get(0);
        }

        static ClaimView of(Claim claim, List<ClaimLog> log) {
            return new ClaimView(claim.getId(), claim.getPersonId(),
                    claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                    claim.getDate(), claim.getDueBy(), claim.getNote(), claim.getStatus(), claim.getNumber(),
                    text(claim.getSettledDue()), claim.getOpenedBy(), claim.isStated(), text(claim.getStatedDue()),
                    claim.getCorrects(), log.stream().map(ClaimView::line).toList(),
                    claim.getDeferredUntil(), claim.getProofs(), claim.getSplitFrom(),
                    claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(), claim.getTags(),
                    claim.getVoidReason());
        }

        /** A log line as shown: {@code <STATUS> by <user> on <date> due=<due>}. */
        private static String line(ClaimLog entry) {
            return entry.getStatus() + " by " + entry.getBy() + " on " + entry.getDate() + " due="
                    + (entry.getDue() == null ? "n/a" : text(entry.getDue()));
        }

        private static String text(BigDecimal figure) {
            return figure == null ? null : figure.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
        }
    }

    /** A claim's amount (with up to two decimals; negative on a correction), date (the sheet's today
     * when left out), note (may be empty), on a correction, the number of the claim it corrects, and its
     * external reference (none when blank), and its tags, comma separated (none when blank). */
    public record ClaimRequest(
            @NotNull @Pattern(regexp = "\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*") String amount,
            LocalDate date,
            @Size(max = 500) String note,
            @Size(max = 120) String corrects,
            @Size(max = 120) String ref,
            @Size(max = 500) String tags) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }

        /** The number named, trimmed; null when none is. */
        String correctsValue() {
            return corrects == null || corrects.isBlank() ? null : corrects.trim();
        }

        /** The reference given, trimmed; null when none is. */
        String refValue() {
            return ref == null || ref.isBlank() ? null : ref.trim();
        }

        /** The tags given, as a claim keeps them (see {@link Claim#tagsOf}); null when none are. */
        String tagsValue() {
            return Claim.tagsOf(tags);
        }
    }

    /** Why a steward rejects a PENDING claim: one word, as it is written into the audit. */
    public record RejectRequest(@NotNull @Pattern(regexp = "\\s*\\S{1,200}\\s*") String reason) {
    }

    /** The reason from the sheet's list a claim is voided with; none when null or blank. */
    public record VoidRequest(@Size(max = 200) String reason) {
    }

    /** The date a claim is deferred until. */
    public record DeferRequest(@NotNull LocalDate until) {
    }

    /** The amount split off a claim: more than 0.00, with up to two decimals. */
    public record SplitRequest(@NotNull @Pattern(regexp = "\\s*\\d{1,10}(\\.\\d{1,2})?\\s*") String amount) {

        BigDecimal amountValue() {
            return new BigDecimal(amount.trim()).setScale(2);
        }
    }

    /** The date a claim is re-dated to. */
    public record RedateRequest(@NotNull LocalDate date) {
    }

    /** The person a claim is moved to, by id. */
    public record ReassignRequest(@NotNull Long personId) {
    }

    /** The claims a bulk change is asked of, by id. */
    public record BulkRequest(@NotNull @Size(max = 1000) List<@NotNull Long> claimIds) {
    }

    /** How a bulk open went: how many claims it opened and refused, and the claims it opened. */
    public record BulkOpenView(int opened, int refused, List<ClaimView> claims) {
    }

    /** How a bulk settle went: how many claims it settled (or left PENDING) and refused, and those claims. */
    public record BulkSettleView(int settled, int refused, List<ClaimView> claims) {
    }

    private final ClaimService service;
    private final ClaimBulkService bulk;

    private final SheetHistory history;

    public ClaimController(ClaimService service, ClaimBulkService bulk, SheetHistory history) {
        this.history = history;
        this.service = service;
        this.bulk = bulk;
    }

    @GetMapping("/claims")
    public List<ClaimView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        if (asOf != null) {
            SheetAsOf then = history.read(sheetId.trim(), asOf);
            Map<Long, List<ClaimLog>> logs = service.logsOf(then.claims());
            return then.claims().stream()
                    .map(c -> ClaimView.of(c, then.logged(logs.getOrDefault(c.getId(), List.of())))).toList();
        }
        return views(service.list(sheetId.trim()));
    }

    /** Every tag ever used on the sheet's claims, sorted. */
    @GetMapping("/tags")
    public List<String> tags(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.tags(sheetId.trim());
    }

    @PostMapping("/people/{personId}/claims")
    @ResponseStatus(HttpStatus.CREATED)
    public ClaimView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return view(service.add(sheetId.trim(), user.trim(), personId, request.amountValue(), request.date(),
                request.note(), request.correctsValue(), request.refValue(), request.tagsValue()));
    }

    @PutMapping("/claims/{claimId}")
    public ClaimView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ClaimRequest request) {
        return view(service.update(sheetId.trim(), user.trim(), claimId, request.amountValue(), request.date(),
                request.note(), request.correctsValue(), request.refValue(), request.tagsValue()));
    }

    @PostMapping("/claims/{claimId}/lock")
    public ClaimView lock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.lock(sheetId.trim(), user.trim(), claimId));
    }

    @PostMapping("/claims/{claimId}/unlock")
    public ClaimView unlock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.unlock(sheetId.trim(), user.trim(), claimId));
    }

    @PostMapping("/claims/{claimId}/open")
    public ClaimView open(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.OPEN));
    }

    @PostMapping("/claims/{claimId}/settle")
    public ClaimView settle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.SETTLED));
    }

    @PostMapping("/claims/{claimId}/approve")
    public ClaimView approve(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.approve(sheetId.trim(), user.trim(), claimId));
    }

    @PostMapping("/claims/{claimId}/reject")
    public ClaimView reject(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RejectRequest request) {
        return view(service.reject(sheetId.trim(), user.trim(), claimId, request.reason().trim()));
    }

    @PostMapping("/claims/{claimId}/void")
    public ClaimView voidClaim(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) @Valid VoidRequest request) {
        String reason = request == null ? null : request.reason();
        return view(service.changeStatus(sheetId.trim(), user.trim(), claimId, ClaimStatus.VOID, reason));
    }

    @PostMapping("/claims/{claimId}/proof")
    public ClaimView addProof(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.addProof(sheetId.trim(), user.trim(), claimId));
    }

    @PostMapping("/claims/{claimId}/remind")
    public ClaimView remind(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.remind(sheetId.trim(), user.trim(), claimId));
    }

    @PostMapping("/claims/{claimId}/resettle")
    public ClaimView resettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(service.resettle(sheetId.trim(), user.trim(), claimId));
    }

    @PostMapping("/claims/{claimId}/defer")
    public ClaimView defer(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid DeferRequest request) {
        return view(service.defer(sheetId.trim(), user.trim(), claimId, request.until()));
    }

    /** Split an amount off the claim: the claim as it is now, then the new claim. */
    @PostMapping("/claims/{claimId}/split")
    public List<ClaimView> split(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid SplitRequest request) {
        return views(service.split(sheetId.trim(), user.trim(), claimId, request.amountValue()));
    }

    @PostMapping("/claims/{claimId}/redate")
    public ClaimView redate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid RedateRequest request) {
        return view(service.redate(sheetId.trim(), user.trim(), claimId, request.date()));
    }

    @PostMapping("/claims/{claimId}/reassign")
    public ClaimView reassign(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable long claimId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid ReassignRequest request) {
        return view(service.reassign(sheetId.trim(), user.trim(), claimId, request.personId()));
    }

    @PostMapping("/claims/bulk-open")
    public BulkOpenView bulkOpen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf,
            @RequestBody @Valid BulkRequest request) {
        if (asOf != null) return new BulkOpenView(0, Set.copyOf(request.claimIds()).size(), List.of());
        ClaimBulkService.Outcome outcome = bulk.open(sheetId.trim(), user.trim(), request.claimIds());
        return new BulkOpenView(outcome.changed().size(), outcome.refused(),
                views(outcome.changed()));
    }

    @PostMapping("/claims/bulk-settle")
    public BulkSettleView bulkSettle(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestHeader(value = AsOfGuard.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf,
            @RequestBody @Valid BulkRequest request) {
        if (asOf != null) return new BulkSettleView(0, Set.copyOf(request.claimIds()).size(), List.of());
        ClaimBulkService.Outcome outcome = bulk.settle(sheetId.trim(), user.trim(), request.claimIds());
        return new BulkSettleView(outcome.changed().size(), outcome.refused(),
                views(outcome.changed()));
    }

    private ClaimView view(Claim claim) {
        return ClaimView.of(claim, service);
    }

    private List<ClaimView> views(List<Claim> claims) {
        return ClaimView.allOf(claims, service);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonWatch;
import net.officefloor.hq.app.person.PersonWatchRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.Action;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.voidreason.VoidReasonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The claims people on each sheet make. A claim left without a date is dated the sheet's entry date,
 * or its today when that is off. A claim's
 * terms are fixed when it is added, from those of its person's grade in force on its date, and its due-by
 * is the terms-th business day after that date, skipping weekends and the holidays on the sheet now; the
 * claim belongs to the period containing that due-by (not its date). Only a DRAFT claim can be edited.
 * No claim whose due-by falls inside a closed period (not only soft-closed) can be added, edited or
 * change status; one added with its due-by inside a soft-closed period is a late entry, and none can be added or edited to a date after its person's retirement date. A claim with a
 * negative amount is a correction: it is refused unless it names, by number, a SETTLED claim of the same
 * person; a claim that is not a correction names none. */
@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final PersonRepository people;
    private final RollupService rollup;
    private final SheetService sheets;
    private final PeriodRepository periods;
    private final SettingsService settings;
    private final PersonWatchRepository watches;
    private final HolidayService holidays;
    private final Audit audit;
    private final SheetTagRepository tagRepository;
    private final VoidReasonService voidReasons;

    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RollupService rollup, SheetService sheets,
            PeriodRepository periods, SettingsService settings, PersonWatchRepository watches, HolidayService holidays,
            Audit audit, SheetTagRepository tagRepository, VoidReasonService voidReasons) {
        this.voidReasons = voidReasons;
        this.tagRepository = tagRepository;
        this.holidays = holidays;
        this.watches = watches;
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.rollup = rollup;
        this.sheets = sheets;
        this.periods = periods;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's claims, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /** The status logs of the claims, by claim id, each oldest first. */
    @Transactional(readOnly = true)
    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
        if (of.isEmpty()) return Map.of();
        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(sheetId, user, personId, amount, date, note, corrects, null);
    }

    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(sheetId, user, personId, amount, date, note, corrects, ref, null);
    }

    /** Every tag ever used on the sheet's claims, sorted. */
    @Transactional(readOnly = true)
    public List<String> tags(String sheetId) {
        return tagRepository.findBySheetIdOrderByTagAsc(sheetId).stream().map(SheetTag::getTag).toList();
    }

    /** Add a claim with the external reference {@code ref} (none when null), refused when another claim
     * on the sheet has it (compared without regard to case), and the tags {@code tags} (see
     * {@link Claim#tagsOf}; none when null). */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
        int terms = termsOf(sheetId, person, dated);
        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
        refuseClosed(sheetId, dueBy);
        person.requireClaimable(dated);
        refuseBadCorrection(sheetId, personId, amount, corrects);
        refuseRefTaken(sheetId, null, ref);
        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
        claim.setRef(ref);
        claim.setTags(tags);
        claim.fixTerms(dated, terms);
        claim.setDueBy(dueBy);
        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
        claim = claims.saveAndFlush(claim);
        log(user, person, claim);
        keepTags(claim);
        List<String> extra = new ArrayList<>();
        if (ref != null) extra.add("ref=" + ref);
        if (tags != null) extra.add("tags=" + tags);
        record("CLAIM_ADDED", user, person, claim, claim.getNumber(), extra.toArray(String[]::new));
        if (claim.isLateEntry()) record("LATE_ENTRY", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    @Transactional
    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tags) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        person.requireClaimable(dated);
        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
        refuseRefTaken(sheetId, claim.getId(), ref);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setCorrects(corrects);
        claim.setDate(dated);
        claim.setNote(noteOf(note));
        claim.setRef(ref);
        claim.setTags(tags);
        keepTags(claim);
        claim.unlock();
        claims.flush();
        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
        rollup.recordSince(sheetId, user, before);
        return claim;
    }

    /** Open the claim's editor for {@code user}, locking the claim for everyone else until it is saved
     * (see {@link #update}) or cancelled (see {@link #unlock}), or the sheet's today changes. Refused,
     * taking no lock, when the claim cannot be edited (not a DRAFT, or dated in a closed period) or
     * another user holds its lock. */
    @Transactional
    public Claim lock(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        LocalDate today = sheets.today(sheetId);
        refuseClosed(sheetId, claim.getDueBy());
        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
        if (claim.isLockedFor(user, today)) throw new ClaimLockedException();
        claim.lock(user, today);
        return claim;
    }

    /** Close {@code user}'s editor of the claim without saving, releasing the lock it holds; a lock
     * another user holds is left alone. */
    @Transactional
    public Claim unlock(String sheetId, String user, long claimId) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        if (user.equals(claim.getLockedBy())) claim.unlock();
        return claim;
    }

    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
     * together with its late charge then (none on a correction); the user who opened it cannot settle it,
     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
     * above the proof threshold in force on its date (refused before the clerk limit is considered). A
     * SETTLED claim can only be voided by a steward, and only while the sheet's today is at most 7 days
     * after its settlement (its status log's SETTLED date); its frozen figure then leaves every total and
     * is recorded as reversed. A voided claim keeps its number, if it had one. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
        return changeStatus(sheetId, user, claimId, next, null);
    }

    /** Move the claim to {@code next} as {@link #changeStatus(String, String, long, ClaimStatus)} does;
     * a void is given {@code voidReason}, which while the sheet's list of void reasons is not empty must
     * be one on it (see {@link VoidReasonService#refuseUnlisted}), and is kept on the claim. */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
        Action action = switch (next) {
            case OPEN -> Action.OPEN;
            case SETTLED -> Action.SETTLE;
            case VOID -> Action.VOID;
            default -> null;
        };
        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
        refuseClosed(sheetId, claim.getDueBy());
        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
            throw new ClaimStatusChangeException();
        }
        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
        if (reversing) refuseLateVoid(sheetId, user, claim);
        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) throw new ClaimSelfSettleException();
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(PersonNotFoundException::new);
        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
