540	    /** Move the claim to {@code next} as {@link #changeStatus(String, String, long, ClaimStatus)} does;
541	     * a void is given {@code voidReason}, which while the sheet's list of void reasons is not empty must
542	     * be one on it (see {@link VoidReasonService#refuseUnlisted}), and is kept on the claim. */
543	    @Transactional
544	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
545	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
546	        Action action = switch (next) {
547	            case OPEN -> Action.OPEN;
548	            case SETTLED -> Action.SETTLE;
549	            case VOID -> Action.VOID;
550	            default -> null;
551	        };
552	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
553	        refuseClosed(sheetId, claim.getDueBy());
554	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
555	            throw new ClaimStatusChangeException();
556	        }
557	        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
558	        if (reversing) refuseLateVoid(sheetId, user, claim);
559	        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
560	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
561	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) throw new ClaimSelfSettleException();
562	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
563	                .orElseThrow(PersonNotFoundException::new);
564	        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
565	        RollupService.Snapshot before = rollup.snapshot(sheetId);
566	        String number = claim.getNumber();
567	        if (next == ClaimStatus.OPEN) {
568	            number = nextNumber(sheetId, claim.getDueBy());
569	            claim.setOpenedBy(user);
570	        }
571	        if (next == ClaimStatus.SETTLED) {
572	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
573	            BigDecimal due = rollup.liveDueOf(claim, figure);
574	            refuseUnproved(claim, due);
575	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
576	            else claim.setSettledDue(due);
577	        }
578	        claim.setStatus(next);
579	        claim.setNumber(number);
580	        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
581	        claims.flush();
582	        log(user, person, claim);
583	        String event = switch (next) {
584	            case OPEN -> "CLAIM_OPENED";
585	            case PENDING -> "CLAIM_PENDING";
586	            case SETTLED -> "CLAIM_SETTLED";
587	            case VOID -> "CLAIM_VOIDED";
588	            case DRAFT -> throw new IllegalStateException();
589	        };
590	        if (next == ClaimStatus.SETTLED) {
591	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
592	            notifyWatchers(user, person, claim);
593	        } else {
594	            List<String> extra = new ArrayList<>();
595	            if (reversing) extra.add("reversed=" + dueText(claim.getSettledDue()));
596	            if (reason != null) extra.add("reason=" + reason);
597	            record(event, user, person, claim, number, extra.toArray(String[]::new));
598	        }
599	        rollup.recordSince(sheetId, user, before);
600	        return claim;
601	    }
