667	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
668	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
669	     * amount, with the same person, date and note, is given the next number, is opened by the user, has
670	     * its due-by fixed now from the terms in force on its date and names the claim's number as the one
671	     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
672	     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
673	     * in a closed period. Both claims are returned, the original first. */
674	    @Transactional
675	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
676	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
677	        refuseClosed(sheetId, claim.getDueBy());
678	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
679	            throw new ClaimStatusChangeException();
680	        }
681	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
682	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
683	                .orElseThrow(PersonNotFoundException::new);
684	        RollupService.Snapshot before = rollup.snapshot(sheetId);
685	        claim.setAmount(claim.getAmount().subtract(amount));
686	        claim.unbind();
687	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
688	        int terms = termsOf(sheetId, person, claim.getDate());
689	        split.fixTerms(claim.getDate(), terms);
690	        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
691	        refuseClosed(sheetId, split.getDueBy());
692	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
693	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
694	        split.setStatus(ClaimStatus.OPEN);
695	        split.setNumber(nextNumber(sheetId, split.getDueBy()));
696	        split.setOpenedBy(user);
697	        split.setSplitFrom(claim.getNumber());
698	        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
699	        split = claims.saveAndFlush(split);
700	        log(user, person, split);
701	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
702	        record("CLAIM_OPENED", user, person, split, split.getNumber());
703	        rollup.recordSince(sheetId, user, before);
704	        return List.of(claim, split);
705	    }
