796	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
797	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
798	     * steward, and when it is dated in a closed period. */
799	    @Transactional
800	    public Claim resettle(String sheetId, String user, long claimId) {
801	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
802	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
803	        refuseClosed(sheetId, claim.getDueBy());
804	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
