810	        claim.setSettledDue(due);
811	        claims.flush();
812	        log(user, person, claim);
813	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
814	        notifyWatchers(user, person, claim);
815	        rollup.recordSince(sheetId, user, before);
816	        return claim;
817	    }
