819	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
820	     * 7 days after the date its status log first shows it SETTLED. */
821	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
822	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
823	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
824	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
825	                .map(ClaimLog::getDate)
826	                .findFirst()
827	                .orElseThrow(ClaimStatusChangeException::new);
828	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
829	    }
