831	    /** The PENDING claim, locked, for a steward to approve or reject. */
832	    private Claim lockPending(String sheetId, String user, long claimId) {
833	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
834	        refuseClosed(sheetId, claim.getDueBy());
835	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
836	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
837	        return claim;
838	    }
839	
840	    private static String dueText(BigDecimal due) {
841	        return due == null ? "n/a" : due.toPlainString();
842	    }
843	
844	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
845	     * (see {@link RollupService#figureOf}). */
846	    public BigDecimal figureOf(Claim claim, Person person) {
847	        return rollup.figureOf(claim, person);
848	    }
849	
850	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
851	     * no figure (see {@link RollupService#shownOf}). */
852	    public BigDecimal shownOf(Claim claim, Person person) {
853	        return rollup.shownOf(claim, person);
854	    }
855	
856	    /** Keep each of the claim's tags among those ever used on its sheet. */
857	    private void keepTags(Claim claim) {
858	        for (String tag : claim.getTags()) {
859	            SheetTag.Key key = new SheetTag.Key(claim.getSheetId(), tag);
860	            if (!tagRepository.existsById(key)) tagRepository.save(new SheetTag(claim.getSheetId(), tag));
861	        }
862	    }
863	
864	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
865	     * it shows now. */
866	    private void log(String user, Person person, Claim claim) {
867	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
868	                rollup.shownOf(claim, person)));
869	    }
870	
871	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
872	     * then any {@code extra} fields. */
873	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
874	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
875	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
876	                "date=" + claim.getDate()));
877	        if (number != null) fields.add("number=" + number);
878	        fields.addAll(List.of(extra));
879	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
880	    }
881	
882	    /** Notify each user watching the person, in the order they started watching, that the claim was
883	     * settled, approved or re-settled. */
884	    private void notifyWatchers(String user, Person person, Claim claim) {
885	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
886	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
887	                    "number=" + claim.getNumber());
888	        }
889	    }
890	
891	    /** The number a claim due by {@code date} is given when opened now: within the period containing
892	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
893	     * period, otherwise the next sheet-wide number. */
894	    private String nextNumber(String sheetId, LocalDate date) {
895	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
896	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
897	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
898	                .findFirst()
899	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
900	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
901	    }
902	
903	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
904	     * the user is a clerk and the due is above the sheet's clerk limit. */
905	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
906	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
907	        BigDecimal limit = settings.clerkLimit(sheetId);
908	        return limit != null && due.compareTo(limit) > 0;
909	    }
910	
911	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
912	     * due is above the proof threshold in force on its date (a due that is n/a is within any threshold). */
913	    private void refuseUnproved(Claim claim, BigDecimal due) {
914	        if (due == null || claim.getProofs() > 0) return;
915	        BigDecimal threshold = settings.proofThresholdOn(claim.getSheetId(), claim.getDate());
916	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
917	    }
918	
919	    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
920	     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
921	    private void refuseNoteless(Claim claim, BigDecimal due) {
922	        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
923	        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
924	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
925	    }
926	
927	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
928	     * the person, and a claim that names one without being a correction. */
929	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
930	        if (amount.signum() >= 0) {
931	            if (corrects != null) throw new ClaimCorrectionException();
932	            return;
933	        }
934	        if (corrects == null) throw new ClaimCorrectionException();
935	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
936	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
937	                .orElseThrow(ClaimCorrectionException::new);
938	    }
939	
940	    /** Refuse the external reference {@code ref} when a claim on the sheet other than {@code claimId} has
941	     * it, compared without regard to case. */
942	    private void refuseRefTaken(String sheetId, Long claimId, String ref) {
943	        if (ref == null) return;
944	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
945	                .filter(other -> !other.getId().equals(claimId))
946	                .ifPresent(other -> {
947	                    throw new ClaimRefTakenException();
948	                });
949	    }
950	
951	    /** Refuse a change to a claim due by {@code date} when a closed period of the sheet contains it. */
952	    private void refuseClosed(String sheetId, LocalDate date) {
953	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
954	    }
955	
956	    private static String noteOf(String note) {
957	        return note == null ? "" : note.trim();
958	    }
959	
960	    /** The terms a claim of the person dated {@code date} is due by: the person's own terms, else those
961	     * of their grade in force on that date, else the sheet's then. */
962	    private int termsOf(String sheetId, Person person, LocalDate date) {
963	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(date), date);
964	    }
965	}
966	-- A claim's tags: trimmed, lower-cased, without repeats, sorted and comma separated; null when it has
967	-- none. sheet_tag keeps every tag ever used on a sheet's claims.
968	ALTER TABLE claim ADD COLUMN tags VARCHAR(1000);
969	CREATE TABLE sheet_tag (
970	    sheet_id VARCHAR(100) NOT NULL,
971	    tag      VARCHAR(500) NOT NULL,
972	    PRIMARY KEY (sheet_id, tag)
973	);
974	-- How many proofs a claim has been given; raised by one at a time while it is neither SETTLED nor VOID.
975	-- The sheet's proof threshold is a dated setting (proof-threshold) kept in sheet_setting.
976	ALTER TABLE claim ADD COLUMN proofs INT NOT NULL DEFAULT 0;
977	-- The reasons a claim can be voided with on a sheet, one row each; while a sheet has any, a void of
978	-- one of its claims names one of them, kept on the claim (null on a claim voided without one).
979	CREATE TABLE sheet_void_reason (
980	    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
981	    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
982	    reason   VARCHAR(200) NOT NULL,
983	    CONSTRAINT sheet_void_reason_unique UNIQUE (sheet_id, reason)
984	);
985	ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
